// This file is generated by AI.

// 快照打包进度/结果对话框: 打开时自动开始打包, 实时显示扫描与打包进度。

import { Button } from '@fluentui/react-components';
import { useEffect, useRef, useState } from 'react';

import { packSnapshot, type SnapshotEvent, type SnapshotResult } from '../commands/snapshot';

interface SnapshotDialogProps {
  /** 项目根目录 */
  source: string;
  /** 输出压缩包路径 */
  destination: string;
  onClose: () => void;
}

type Phase = 'scanning' | 'packing' | 'done';

interface SnapshotProgress {
  phase: Phase;
  // 扫描
  scanFile: string;
  scanCount: number;
  scanSize: number;
  // 打包
  packCount: number;
  packProcessed: number;
  packSize: number;
  packCompressed: number;
  // 过程错误 (最终以结果为准)
  errors: string[];
  // 结果
  result?: SnapshotResult;
}

const INITIAL: SnapshotProgress = {
  phase: 'scanning',
  scanFile: '',
  scanCount: 0,
  scanSize: 0,
  packCount: 0,
  packProcessed: 0,
  packSize: 0,
  packCompressed: 0,
  errors: [],
};

function applyEvent(progress: SnapshotProgress, event: SnapshotEvent): SnapshotProgress {
  switch (event.type) {
    case 'scanStart':
      return { ...INITIAL };
    case 'scanFile':
      return {
        ...progress,
        scanFile: lastSegment(event.path),
        scanCount: event.index,
        scanSize: event.cumulativeSize,
      };
    case 'scanError':
      return { ...progress, errors: [...progress.errors, event.message] };
    case 'scanComplete':
      return { ...progress, scanCount: event.count, scanSize: event.totalSize };
    case 'packStart':
      return {
        ...progress,
        phase: 'packing',
        packCount: event.count,
        packProcessed: 0,
        packSize: 0,
        packCompressed: 0,
      };
    case 'packFile':
      return {
        ...progress,
        packProcessed: event.index,
        packSize: event.cumulativeSize,
        packCompressed: event.cumulativeCompressedSize,
      };
    case 'packError':
      return { ...progress, errors: [...progress.errors, event.message] };
    case 'packComplete':
      return { ...progress, packCompressed: event.finalSize };
  }
}

/** 取路径的最后一段 (文件名)。 */
function lastSegment(path: string): string {
  return path.split(/[\\/]/).pop() ?? path;
}

/** 人类可读的文件体积。 */
function formatSize(bytes: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return unit === 0 ? `${bytes} B` : `${value.toFixed(1)} ${units[unit]}`;
}

export function SnapshotDialog({ source, destination, onClose }: SnapshotDialogProps) {
  const [progress, setProgress] = useState<SnapshotProgress>(INITIAL);
  const started = useRef(false);

  // 打开对话框即开始打包
  useEffect(() => {
    if (started.current) return;
    started.current = true;
    let cancelled = false;
    void packSnapshot(source, destination, (event) => {
      if (!cancelled) setProgress((prev) => applyEvent(prev, event));
    })
      .then((result) => {
        if (!cancelled) setProgress((prev) => ({ ...prev, phase: 'done', result }));
      })
      .catch((error) => {
        if (!cancelled) {
          setProgress((prev) => ({
            ...prev,
            phase: 'done',
            result: { count: 0, totalSize: 0, finalSize: 0, aborted: true, errors: [String(error)] },
          }));
        }
      });
    return () => {
      cancelled = true;
    };
  }, [source, destination]);

  const { phase, result } = progress;
  const errors = result?.errors ?? progress.errors;
  const packPercent = progress.packCount === 0 ? 0 : Math.round((progress.packProcessed / progress.packCount) * 100);
  const packRatio = progress.packSize === 0 ? 0 : Math.round((progress.packCompressed / progress.packSize) * 100);

  return (
    <div className="modal-backdrop" onClick={() => phase === 'done' && onClose()}>
      <div className="modal-surface snapshot-surface" onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">生成快照</h2>

        <p className="snapshot-destination" title={destination}>
          {destination}
        </p>

        {phase !== 'done' && (
          <>
            {phase === 'scanning' ? (
              <p className="snapshot-line">
                正在收集 {progress.scanFile || '…'} · {progress.scanCount} 个文件 · {formatSize(progress.scanSize)}
              </p>
            ) : (
              <>
                <div className="snapshot-bar">
                  <div className="snapshot-bar-fill" style={{ width: `${packPercent}%` }} />
                </div>
                <p className="snapshot-line">
                  {progress.packProcessed}/{progress.packCount} ({packPercent}%) · {formatSize(progress.packSize)} →{' '}
                  {formatSize(progress.packCompressed)} (压缩 {packRatio}%)
                </p>
              </>
            )}
            {errors.length > 0 && (
              <ul className="snapshot-errors">
                {errors.map((message, i) => (
                  <li key={i}>{message}</li>
                ))}
              </ul>
            )}
          </>
        )}

        {phase === 'done' && result && (
          <>
            {result.aborted ? (
              <p className="snapshot-error-text">打包被终止, 压缩包未完整生成</p>
            ) : result.errors.length > 0 ? (
              <>
                <p className="snapshot-error-text">打包完成, 共 {result.errors.length} 个错误</p>
                <ul className="snapshot-errors">
                  {result.errors.map((message, i) => (
                    <li key={i}>{message}</li>
                  ))}
                </ul>
              </>
            ) : (
              <p className="snapshot-success">
                已生成快照: {result.count} 个文件 · {formatSize(result.totalSize)} → {formatSize(result.finalSize)}
              </p>
            )}
          </>
        )}

        <div className="modal-actions">
          <Button appearance="primary" disabled={phase !== 'done'} onClick={onClose}>
            关闭
          </Button>
        </div>
      </div>
    </div>
  );
}
